import{_ as t,o,c as s,a4 as r}from"./chunks/framework.bruR1JhL.js";const c=JSON.parse('{"title":"Getting started","description":"What Tilepress needs, how to install, update and remove it, and how to open a file in a tool.","frontmatter":{"title":"Getting started","description":"What Tilepress needs, how to install, update and remove it, and how to open a file in a tool."},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md","lastUpdated":1795509372000}'),a={name:"docs/index.md"};function n(i,e,l,d,h,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Tilepress is a Windows app with PDF and image tools. It works on the files on your own PC: nothing is uploaded. This page covers installing it, the first launch, and the ways to get a file into a tool.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><ul><li><strong>Windows 10 or Windows 11, 64-bit.</strong> The installer is for x64 PCs.</li><li><strong>The Microsoft Edge WebView2 Runtime.</strong> Tilepress draws its window with it. It comes with Windows 11 and with up-to-date Windows 10. On an older PC that doesn&#39;t have it, install the Evergreen WebView2 Runtime from <a href="https://developer.microsoft.com/microsoft-edge/webview2/" target="_blank" rel="noreferrer">Microsoft&#39;s WebView2 page</a>.</li><li><strong>A screen with room for the window.</strong> The window can&#39;t be made smaller than 980 × 600 pixels.</li><li><strong>An internet connection only for a few things:</strong> the one-time LaTeX engine download, each AI model the first time you use its tool, and web pages you ask a tool to load. Everything else works offline. See <a href="/tilepress/docs/privacy">Privacy</a> for the full list.</li></ul><p>Some tools use other software when it&#39;s there:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Uses</th><th>Without it</th></tr></thead><tbody><tr><td>Word to PDF, PowerPoint to PDF, Excel to PDF</td><td>Microsoft Office, or LibreOffice</td><td>These three tools can&#39;t convert. Install either one, then restart Tilepress.</td></tr><tr><td>PDF to Word</td><td>Microsoft Word, for the closest layout</td><td>A built-in converter is used.</td></tr><tr><td>OCR PDF</td><td>Tesseract OCR, if it&#39;s installed</td><td>Windows OCR is used, with the languages installed in Windows that include text recognition.</td></tr><tr><td>LaTeX editor</td><td>An installed LaTeX engine (Tectonic, or pdfLaTeX, XeLaTeX or LuaLaTeX from MiKTeX or TeX Live)</td><td>Tilepress downloads Tectonic on first launch.</td></tr><tr><td>Upscale Image, Remove background</td><td>A graphics card, through DirectML</td><td>The models run on the processor instead. It&#39;s slower, but the result is the same.</td></tr></tbody></table><h2 id="install-tilepress" tabindex="-1">Install Tilepress <a class="header-anchor" href="#install-tilepress" aria-label="Permalink to &quot;Install Tilepress&quot;">​</a></h2><ol><li>Download the installer (<code>.msi</code>) from the <a href="/tilepress/download">Download</a> page.</li><li>Double-click it. On the welcome page click <strong>Next</strong>, then <strong>Install</strong>.</li><li>On the last page, <strong>Launch Tilepress</strong> is ticked. Click <strong>Finish</strong> to start Tilepress.</li></ol><p>The installer doesn&#39;t ask for administrator rights. It installs Tilepress for your Windows account only, in <code>%LocalAppData%\\Programs\\Tilepress</code>, and adds Tilepress to the Start menu.</p><h3 id="install-for-everyone-on-the-pc" tabindex="-1">Install for everyone on the PC <a class="header-anchor" href="#install-for-everyone-on-the-pc" aria-label="Permalink to &quot;Install for everyone on the PC&quot;">​</a></h3><p>To install in Program Files for every user of the PC, open Command Prompt or Windows Terminal <strong>as administrator</strong>, go to the folder that holds the installer, and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>msiexec /i Tilepress-x64.msi ALLUSERS=1</span></span></code></pre></div><p>Use the name of the file you downloaded if it&#39;s different.</p><h2 id="the-first-launch" tabindex="-1">The first launch <a class="header-anchor" href="#the-first-launch" aria-label="Permalink to &quot;The first launch&quot;">​</a></h2><p>Tilepress opens with three panels: the <strong>Explorer</strong> on the left, the tools in the middle, and the <strong>Preview</strong> on the right. The Explorer starts in your home folder. After that it reopens the last folder you were in. <a href="/tilepress/docs/interface">The Tilepress window</a> explains every part.</p><h3 id="the-latex-engine-downloads-in-the-background" tabindex="-1">The LaTeX engine downloads in the background <a class="header-anchor" href="#the-latex-engine-downloads-in-the-background" aria-label="Permalink to &quot;The LaTeX engine downloads in the background&quot;">​</a></h3><p>If no LaTeX engine is installed on your PC, Tilepress sets one up the first time it starts:</p><ol><li>It downloads Tectonic 0.15.0 (about 19 MB) and checks it against its known SHA-256 checksum. A file that doesn&#39;t match is thrown away.</li><li>It compiles a small test document once, so Tectonic downloads the LaTeX packages most documents need (about 12 MB more).</li></ol><p>This takes about two minutes and happens only once. The status bar at the bottom of the middle panel shows the progress: <strong>Downloading LaTeX engine…</strong>, then <strong>Installing LaTeX engine…</strong> and <strong>Fetching LaTeX packages…</strong>. You can use every other tool in the meantime.</p><p>If the setup fails, for example because you&#39;re offline, the status bar shows <strong>LaTeX setup failed</strong>. Click the status button in the top bar and choose <strong>Retry LaTeX setup</strong>, or just start Tilepress again later: it tries again on every start until the setup succeeds.</p><p>Nothing else is downloaded at start-up. The AI tools download their model the first time you use them, and tell you so first.</p><h2 id="open-a-file-in-a-tool" tabindex="-1">Open a file in a tool <a class="header-anchor" href="#open-a-file-in-a-tool" aria-label="Permalink to &quot;Open a file in a tool&quot;">​</a></h2><p>First pick a tool. Choose <strong>Documents</strong> or <strong>Images</strong> at the left of the top bar, then a category tab, then the tool in the row underneath. Or press <kbd>Ctrl</kbd>+<kbd>K</kbd>, type part of the tool&#39;s name or what it does (for example <em>merge</em>, <em>sign</em> or <em>word</em>), and press <kbd>Enter</kbd>.</p><p>Then give the tool a file in any of these ways:</p><ul><li><strong>Select it in the Explorer.</strong> When the selected file suits the open tool, the tool shows a <strong>Use</strong> button with the file&#39;s name. Click it.</li><li><strong>Drag it from the Explorer</strong> onto the tool. Dragging works from Tilepress&#39;s own Explorer pane; files dragged in from Windows File Explorer aren&#39;t picked up.</li><li><strong>Right-click it in the Explorer</strong> and choose a tool from the menu (see the table below).</li><li><strong>Use the buttons in the Preview pane.</strong> A PDF has <strong>PDF tools</strong>, an image has <strong>Edit photo</strong>, and a file that can be converted has <strong>Convert to PDF</strong>.</li><li><strong>Use the tool&#39;s own button</strong>, such as <strong>Open PDF…</strong>, <strong>Open image…</strong>, <strong>Add PDFs…</strong> or <strong>Add images…</strong>, to pick a file in a Windows file dialog.</li></ul><p>The right-click menu offers these tools:</p><table tabindex="0"><thead><tr><th>File</th><th>Menu entries</th></tr></thead><tbody><tr><td>PDF</td><td><strong>Open in PDF tools</strong>, <strong>Add to Merge PDF</strong>, <strong>Edit PDF</strong>, <strong>Convert from PDF</strong>, <strong>Sign PDF</strong>, <strong>Protect PDF</strong>, <strong>Print…</strong></td></tr><tr><td>Image (JPG, PNG, WebP, HEIC, HEIF, AVIF, GIF, BMP, TIFF, ICO)</td><td><strong>Edit photo</strong>, <strong>Compress image</strong>, <strong>Resize image</strong>, <strong>Crop image</strong>, <strong>Add to collage</strong>, <strong>Remove background</strong>, <strong>Upscale image</strong>, and <strong>Convert to PDF</strong> for JPG, PNG, GIF, BMP, TIFF and WebP</td></tr><tr><td>Word, PowerPoint, Excel, CSV, HTML, Markdown</td><td><strong>Convert to PDF</strong> (it picks the matching tool)</td></tr><tr><td><code>.tex</code></td><td><strong>Open in LaTeX editor</strong></td></tr></tbody></table><p><strong>Open in PDF tools</strong> opens the PDF in the page tool you used last (Organize PDF if that was Merge PDF). <strong>Convert from PDF</strong> opens it in the From PDF tool you used last.</p><div class="tip custom-block"><p class="custom-block-title">One open PDF, one open image</p><p>The tools that work on a single PDF share it. Open a file in Split PDF, switch to Watermark PDF or Sign PDF, and the same file is already open. Merge PDF keeps its own list, and Protect PDF and Repair PDF keep their own file. In the same way, Crop Image, the AI tools and the Photo editor share one open image, while the batch image tools each keep their own list.</p></div><p>Every tool saves a <strong>new</strong> file and leaves the original alone. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the <strong>Saved</strong> card that appears afterwards.</p><h2 id="update-tilepress" tabindex="-1">Update Tilepress <a class="header-anchor" href="#update-tilepress" aria-label="Permalink to &quot;Update Tilepress&quot;">​</a></h2><p>Download the newer installer and run it. It replaces the installed version and keeps your pins, settings, history and downloaded models. Close Tilepress before you install the update.</p><p>An older installer won&#39;t install over a newer version. It stops with the message &quot;A newer version of Tilepress is already installed.&quot;</p><h2 id="uninstall-tilepress" tabindex="-1">Uninstall Tilepress <a class="header-anchor" href="#uninstall-tilepress" aria-label="Permalink to &quot;Uninstall Tilepress&quot;">​</a></h2><p>Open <strong>Settings</strong> &gt; <strong>Apps</strong> &gt; <strong>Installed apps</strong>, find <strong>Tilepress</strong>, and choose <strong>Uninstall</strong>. You can also run <code>msiexec /x</code> with the installer file.</p><p>Uninstalling removes the program but keeps your data in <code>%LOCALAPPDATA%\\Tilepress</code>: settings, pins, history, the log, the LaTeX engine and the AI models. To remove those too, delete that folder after uninstalling. Tectonic keeps its downloaded LaTeX packages in <code>%LOCALAPPDATA%\\TectonicProject</code>, which you can delete as well. <a href="/tilepress/docs/privacy">Privacy</a> lists what each item in the data folder is.</p><h2 id="the-tools" tabindex="-1">The tools <a class="header-anchor" href="#the-tools" aria-label="Permalink to &quot;The tools&quot;">​</a></h2><p>Documents:</p><ul><li><a href="/tilepress/docs/pdf-pages">Combine, split &amp; pages</a>: Merge PDF, Split PDF, Organize PDF, Rotate PDF, Crop PDF, Page numbers</li><li><a href="/tilepress/docs/to-pdf">Convert to PDF</a>: Word, PowerPoint, Excel, images, HTML and Markdown to PDF</li><li><a href="/tilepress/docs/from-pdf">Convert from PDF</a>: PDF to Word, PowerPoint, Excel, JPG and Markdown</li><li><a href="/tilepress/docs/edit">Edit, forms &amp; OCR</a>: Edit PDF, OCR PDF, PDF Forms, Watermark PDF</li><li><a href="/tilepress/docs/security">Security, signing &amp; size</a>: Protect PDF, Sign PDF, Compress PDF, Repair PDF</li><li><a href="/tilepress/docs/print">Printing</a>: Advanced Print</li><li><a href="/tilepress/docs/latex">LaTeX</a>: the LaTeX editor</li></ul><p>Images:</p><ul><li><a href="/tilepress/docs/img-optimize">Format &amp; size</a>: Compress Image, Resize Image, Convert to JPG, Convert from JPG</li><li><a href="/tilepress/docs/img-layout">Crop, rotate, collage &amp; capture</a>: Crop Image, Rotate Image, Photo collage, HTML to Image</li><li><a href="/tilepress/docs/img-ai">AI enhancements</a>: Upscale Image, Remove background, Blur face</li><li><a href="/tilepress/docs/img-edit">Edit &amp; brand</a>: Photo editor, Watermark Image</li></ul><p>Something not working? See <a href="/tilepress/support">Support</a>.</p>',42)])])}const m=t(a,[["render",n]]);export{c as __pageData,m as default};
